-- A57: batch b002_de, chunk 2 (25 videos for learners of de). Guarded: nothing is written when a row of
-- this chunk exists already (the whole transaction stops); English (media_exercise_sets) is not touched.
begin;
do $g$ begin
  if exists (select 1 from public.media_exercise_sets_l10n where learning_language = 'de' and media_id in (5712,406,378,6,7946,7932,7996,4209,7844,4156,8036,515,673,5458,343,5594,94,7981,7145,70,747,7870,7016,8001,7744)) then
    raise exception 'A57 out/b002_de_02.sql: rows exist already - nothing written';
  end if;
end $g$;
do $g$ begin
  if (select count(*) from public.media_exercise_sets_l10n where learning_language = 'de' and media_id in (5712,406,378,6,7946,7932,7996,4209,7844,4156,8036,515,673,5458,343,5594,94,7981,7145,70,747,7870,7016,8001,7744)) <> 25 then
    raise exception 'A57 out/b002_de_02.sql: not 25 rows after the insert';
  end if;
end $g$;
commit;
